  <script>
    // Normalise typed or pasted Arabic-Indic / Eastern digits to Western Latin digits
    function toWesternDigits(str) {
      if (!str) return '';
      return str
        .replace(/[٠-٩]/g, d => d.charCodeAt(0) - 1632)
        .replace(/[۰-۹]/g, d => d.charCodeAt(0) - 1776);
    }

    const boxes = Array.from(document.querySelectorAll('.otp-box'));
    const verifyBtn = document.getElementById('verifyBtn');
    const countdownEl = document.getElementById('countdown');
    const countdownBox = document.getElementById('countdownBox');
    const resendBtn = document.getElementById('resendBtn');

    function checkCompletion() {
      const isComplete = boxes.every(box => box.value.trim().length === 1);
      verifyBtn.disabled = !isComplete;
    }

    // Input management: auto-advance, backspace navigation, digit filtering
    boxes.forEach((box, index) => {
      box.addEventListener('input', (e) => {
        const normalized = toWesternDigits(box.value).replace(/\D/g, '');
        box.value = normalized ? normalized.slice(-1) : '';

        if (box.value) {
          box.classList.add('filled');
          if (index < boxes.length - 1) {
            boxes[index + 1].focus();
          }
        } else {
          box.classList.remove('filled');
        }
        checkCompletion();
      });

      box.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace' && !box.value && index > 0) {
          boxes[index - 1].focus();
          boxes[index - 1].value = '';
          boxes[index - 1].classList.remove('filled');
          checkCompletion();
        }
      });

      // Handle pasting whole OTP (support Western & Arabic-Indic digits)
      box.addEventListener('paste', (e) => {
        e.preventDefault();
        const clipboard = (e.clipboardData || window.clipboardData).getData('text');
        const digits = toWesternDigits(clipboard).replace(/\D/g, '');

        if (!digits) return;

        let cur = index;
        for (let i = 0; i < digits.length && cur < boxes.length; i++) {
          boxes[cur].value = digits[i];
          boxes[cur].classList.add('filled');
          cur++;
        }

        if (cur < boxes.length) {
          boxes[cur].focus();
        } else {
          boxes[boxes.length - 1].focus();
        }
        checkCompletion();
      });
    });

    // 45-Second Countdown Timer Implementation
    let timeLeft = 45;
    let timerInterval = null;

    function startTimer() {
      timeLeft = 45;
      countdownBox.style.display = 'inline-block';
      resendBtn.style.display = 'none';
      updateTimerDisplay();

      clearInterval(timerInterval);
      timerInterval = setInterval(() => {
        timeLeft--;
        updateTimerDisplay();

        if (timeLeft <= 0) {
          clearInterval(timerInterval);
          countdownBox.style.display = 'none';
          resendBtn.style.display = 'inline-block';
        }
      }, 1000);
    }

    function updateTimerDisplay() {
      const minutes = Math.floor(timeLeft / 60);
      const seconds = timeLeft % 60;
      countdownEl.textContent = `${minutes}:${seconds.toString().padStart(2, '0')}`;
    }

    resendBtn.addEventListener('click', () => {
      // Clear inputs
      boxes.forEach(b => {
        b.value = '';
        b.classList.remove('filled');
      });
      boxes[0].focus();
      checkCompletion();
      startTimer();
    });

    verifyBtn.addEventListener('click', () => {
      const enteredCode = boxes.map(b => b.value).join('');
      verifyBtn.textContent = 'جاري التحقق...';
      verifyBtn.disabled = true;

      setTimeout(() => {
        alert('تم تأكيد رمز التحقق بنجاح: ' + enteredCode);
        verifyBtn.innerHTML = `<span>تأكيد</span>
          <svg class="icon-directional" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
            <line x1="5" y1="12" x2="19" y2="12"></line>
            <polyline points="12 5 19 12 12 19"></polyline>
          </svg>`;
        verifyBtn.disabled = false;
      }, 800);
    });

    // Start timer on load
    startTimer();
  </script>
